// Project-aspect standard pack: the self-growing product research wiki
// (compile-once/refine-in-place, cited, dated, isolated behind the reviewed
// product-requirements crossing point). The folder is the classifier: the two
// reserved names (product-requirements/, sample-data/) have fixed meaning;
// everything else under product-wiki/ is wiki space. Fingerprinted by the
// standard's one structural constant — the sink.
import { SINK_README } from './lib.mjs';
import layout from './layout.mjs';
import pageSections from './page-sections.mjs';
import keyInsights from './key-insights.mjs';
import growthLog from './growth-log.mjs';
import sources from './sources.mjs';
import freshness from './freshness.mjs';
import isolation from './isolation.mjs';

export default {
  id: 'product-wiki',
  ruleRoutingGuidance: {
    belongs: 'agent-maintained market, user and competitor research wikis — cited pages, growth logs, the reviewed product-requirements sink',
    excludes: 'how the product is built or specced — that is spec-driven-product; requirement proofs are executable-requirements',
  },
  badge: 'badge.svg',
  marker: SINK_README,
  detect: (ctx) => ctx.tracked.includes(SINK_README),
  prose: 'RULES.md',
  // The isolation wall rides the barriers mechanism: this pack requires
  // barriers and CONTRIBUTES the fixed barrier as manifest data
  // (isolation.mjs — pure data, no cross-pack import; pack-independence).
  requires: ['barriers'],
  contributes: { barriers: [isolation] },
  // Adoption interview: the standard takes no config (the layout IS the config),
  // but a wiki with no research scope is a hollow skeleton — the answers frame
  // WHICH wikis get seeded and what the competitor set is measured against. They
  // record as intent on the entry (`answers`), never as config. Read the repo's
  // own product brief/spec first and confirm, rather than re-asking cold.
  questions: [
    {
      id: 'product',
      prompt: "What is the product — what does it do, and what is the core value it delivers? If the repo already carries a product brief or spec, read it and confirm rather than asking cold.",
      distill: 'recorded as intent on this entry (the pack takes no config); it names what the research is about and frames every seeded wiki',
    },
    {
      id: 'users',
      prompt: 'Who are the users or customers — the segments whose needs the research must track?',
      distill: 'recorded as intent; scopes the user-research wiki and whose problems the findings answer to',
    },
    {
      id: 'market',
      prompt: 'What market or category is this in, and who are the main competitors or alternatives? This is what the competitor research is scoped against.',
      distill: 'recorded as intent; names the competitor set the initial competitor-landscape wiki is seeded from',
    },
  ],
  worldRules: [layout, pageSections, keyInsights, growthLog, sources, freshness],
  // The pack's scheduled task — wiki-growth, the weekly research pass — lives in
  // this pack's `tasks/wiki-growth/`, discovered by the scheduler's filesystem
  // scan (engine/scheduler/discover.mjs), not declared here.
};
=====isolation.mjs
import { PRODUCT_ROOT, SINK_DIR } from './lib.mjs';

// The wall: nothing outside product-wiki/ may reference the self-growing wiki
// folders; product-wiki/product-requirements is the one reviewed crossing point.
// A CONTRIBUTED barrier: this module is pure data the barriers pack builds into
// the rule (product-wiki `requires` barriers and carries this under
// `contributes` on its manifest — the declaration-and-configuration composition
// pack-independence mandates). This edge and product-wiki-layout are a designed
// pair — the glob target fails closed ("matched no directories", blocking) on an
// empty product-wiki/ expansion, and layout owns the missing-skeleton complaint.
// Under the structural standard a renamed wiki folder is still a wiki folder,
// still barred — no per-folder disarm hole.
//
// Edge notes (each empirically verified against a real consumer tree):
// - to 'product-wiki/*' bars every direct CHILD DIRECTORY of product-wiki/; files
//   directly under product-wiki/ (the index README) stay reachable — a repo's root
//   CLAUDE.md legitimately links product-wiki/README.md.
// - allow keeps the crossing point reachable from every guarded file.
// - except 'product-wiki' unguards the whole product-wiki/ subtree (wikis reference
//   each other, sample-data, and outward freely — the wall is one-directional)
//   and satisfies the root-guard validation for the glob target.
// - except '.claudinite-checks.json': the settings file legitimately spells
//   wiki paths (accept entries, historical config) — configuration is not a
//   dependency.
// - matchUniqueFilenames OFF: wiki/sample-data filenames are agent-written,
//   so leaving the unique-basename layer on would let every distinctive
//   filename the growth routine invents become a repo-wide barred bare name
//   outside the consumer's review. Path references still fire.
// - No baked reviewed-exceptions, and consumers can't add any to a
//   pack-shipped edge — crossingExcuse points each finding at the lever that
//   works (an accept; see packs/product-wiki/README.md). Unlike a rule-owned
//   except, accepts are not staleness-audited — prune them by hand.
export default {
  id: 'product-wiki-isolation',
  description: 'Nothing outside product-wiki/ may reference the self-growing wiki folders — product-wiki/product-requirements is the only crossing point',
  why: 'the wikis are agent-rewritten, loosely-sourced research — code, tests, and docs that silently depend on them inherit unreviewed churn',
  doc: 'packs/product-wiki/README.md',
  crossingExcuse: 'if the crossing is deliberate, excuse it with accept: [{ "rule": "product-wiki-isolation", "path": "<file>", "reason": "..." }] in .claudinite-checks.json (a pack-shipped barrier takes no per-rule except entries — see packs/product-wiki/README.md)',
  edges: [{
    from: '.',
    to: `${PRODUCT_ROOT}/*`,
    allow: [SINK_DIR],
    matchUniqueFilenames: false,
    except: [PRODUCT_ROOT, '.claudinite-checks.json'],
    reason: 'the self-growing product wikis and their sample data are autonomous research the repo must not depend on; product-wiki/product-requirements is the one reviewed crossing point',
  }],
};
=====lib
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { under } from '../../engine/checks/helpers/path-containment.mjs';

// Shared helpers and the standard's path constants — spelled ONCE here so the
// checks, the manifest, and the barrier can't drift apart. The wiki set is
// STRUCTURAL, not configured: a wiki page is a README.md at depth >= 2 under
// product-wiki/, outside the two reserved subtrees (product-requirements/ — the
// human-reviewed sink — and sample-data/ — illustrative assets). No wikis
// manifest exists anywhere, so a renamed or newly added wiki folder is
// classified correctly with nothing to drift (folder-is-the-classifier).
export const PRODUCT_ROOT = 'product-wiki';
export const SINK_DIR = 'product-wiki/product-requirements';
export const SAMPLE_DATA_DIR = 'product-wiki/sample-data';
export const INDEX_README = 'product-wiki/README.md';
export const SINK_README = 'product-wiki/product-requirements/README.md';

export function wikiPages(files) {
  return files.filter(
    (f) => /^product-wiki\/.+\/README\.md$/.test(f) && !under(f, SINK_DIR) && !under(f, SAMPLE_DATA_DIR)
  );
}

// One bullet/date grammar for every check that reads a growth log: a top-level
// bullet (-, * or + at column 0) leading with its YYYY-MM-DD run date, bold or
// plain — the invariant is dating, not typography. Date.UTC ROLLS OVER
// out-of-range parts (2026-02-30 → March 2) instead of failing, so calendar
// validity needs the explicit round-trip below.
export const BULLET = /^[-*+]\s/;
export const DATED = /^[-*+]\s+(?:\*\*)?(\d{4})-(\d{2})-(\d{2})(?:\*\*)?\b/;
export function realDateUTC(y, mo, d) {
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d
    ? dt.getTime() : null;
}

// Blank out fenced code blocks, preserving line count — a template embedded in
// a ``` fence must neither satisfy a section requirement nor feed bullets into
// the section scans. Every section reader below works on the stripped text.
function stripFences(text) {
  let inFence = false;
  return text.split('\n').map((l) => {
    if (/^\s*(```|~~~)/.test(l)) { inFence = !inFence; return ''; }
    return inFence ? '' : l;
  });
}

const headingRe = (name) => new RegExp(`^##\\s+${name}\\b`, 'i');

// The heading text of the page's first real (non-fenced) `## ` section, or null
// when the page has none. The position half of the key-insights contract:
// "opens with" is checkable only as "no other `##` section precedes it" —
// the title and a sentence or two of framing prose before it are fine.
export function firstSection(text) {
  const line = stripFences(text).find((l) => /^##\s/.test(l));
  return line === undefined ? null : line.replace(/^##\s+/, '').trim();
}

// Does the page carry a real (non-fenced) `## <name>` section heading?
// The single definition of the heading contract — sectionBody anchors on the
// same regex, so "present" and "readable" can never disagree.
export function hasSection(text, name) {
  const re = headingRe(name);
  return stripFences(text).some((l) => re.test(l));
}

// The lines of the `## <name>` section (case-insensitive; suffix words after
// the name are fine — "## Open questions (for the next pass)") up to the next
// `## ` heading or EOF, fenced content blanked. Each entry carries its
// 1-indexed file line so findings can pin the offending bullet. Returns null
// when the heading is absent — callers skip then, because the missing heading
// is page-sections' finding (never double-report).
export function sectionBody(text, name) {
  const lines = stripFences(text);
  const re = headingRe(name);
  const start = lines.findIndex((l) => re.test(l));
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i++) {
    if (/^##\s/.test(lines[i])) { end = i; break; }
  }
  return lines.slice(start + 1, end).map((t, i) => ({ line: start + 2 + i, text: t }));
}

// The pack takes no config — the product-wiki/ layout IS the standard. A config
// object on the pack entry is a settings mistake (probably a misremembered
// knob), surfaced once, by the layout check only (no cascade). Deliberately
// pack-local rather than a runner-level manifest flag: no other pack rejects
// config yet, and a core seam for it can subsume this when a second pack needs
// one. Known limit: riding a rule means rules:{"product-wiki-layout":"off"}
// silences the guard along with the check.
export function configGuard(ctx, rule) {
  const cfg = ctx.config?.packConfig?.['product-wiki'];
  if (cfg === undefined || cfg === null) return [];
  return [finding(rule, {
    file: '.claudinite-checks.json',
    what: 'product-wiki config: the pack takes no config — the product-wiki/ layout is the standard',
    fix: 'remove the "config" object from the product-wiki pack entry (to silence the freshness advisory use rules: {"product-wiki-freshness": "off"})',
  })];
}

import { finding } from '../../engine/checks/helpers/findings.mjs';
import { wikiPages, sectionBody, DATED, realDateUTC } from './lib.mjs';

// The staleness nag — ADVISORY by design, never blocking: it is time-driven
// and directional (it goes red with no change to the repo), which must never
// block a Stop or fail CI. It exists because it is the only in-repo observer
// for the real failure mode "the unattended growth channel silently stopped
// firing" — ~6 weekly cycles of silence earns a nag. Per-page (one active wiki
// must not mask starved siblings), gated on mode 'all' (a whole-repo
// assertion; the Stop hook and CI both run 'all', so coverage is unchanged).
//
// Only ENTRY dates count — the leading date of a top-level bullet, lib.mjs's
// DATED grammar shared with the growth-log check — never a date mentioned in
// an entry's body or the section's prose, which would silently reset the
// staleness clock this advisory exists to watch. Entry dates more than 2 days
// in the future are discarded so a typo'd future date can't mark a page fresh
// forever. Silence it with rules: {"product-wiki-freshness": "off"}.
const WINDOW_DAYS = 45;
const DAY = 86_400_000;

const rule = {
  id: 'product-wiki-freshness',
  severity: 'advisory',
  doc: 'packs/product-wiki/README.md',
  description: `A wiki page whose newest Growth log entry is older than ${WINDOW_DAYS} days needs a growth pass`,
  why: "a wiki that stopped growing silently stops being true — staleness must reach a human even when the unattended growth channel isn't firing",

  run(ctx) {
    if (ctx.mode !== 'all') return [];
    const out = [];
    const now = ctx.now ?? Date.now(); // ctx.now: injectable clock for tests / future core seam
    for (const page of wikiPages(ctx.files)) {
      const text = ctx.read(page);
      if (text === null) continue;
      const section = sectionBody(text, 'growth log');
      if (section === null) continue;
      const dates = [];
      for (const { text: t } of section) {
        const m = DATED.exec(t);
        if (!m) continue; // undated/malformed bullets are growth-log's territory
        const ts = realDateUTC(+m[1], +m[2], +m[3]);
        if (ts !== null && ts <= now + 2 * DAY) dates.push(ts);
      }
      if (!dates.length) continue;
      const newest = Math.max(...dates);
      const age = Math.floor((now - newest) / DAY);
      if (age > WINDOW_DAYS) {
        out.push(finding(rule, {
          file: page,
          what: `newest Growth log entry is ${age} days old (${new Date(newest).toISOString().slice(0, 10)}) — past the ${WINDOW_DAYS}-day freshness window`,
          fix: "run a product-wiki growth pass (in-session: \"grow the product wiki\"; method: the canon's packs/product-wiki/tasks/wiki-growth/task.md, mounted under .claudinite/ in consumers), or confirm this repo's scheduler workflow is wired and the wiki-growth task is on its schedule; silence via rules: {\"product-wiki-freshness\": \"off\"}",
        }));
      }
    }
    return out;
  },
};

export default rule;
=====findings helper
export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
  return {
    rule: rule.id,
    severity: severity || rule.severity,
    file,
    line,
    what,
    why: why || rule.why,
    fix,
    doc: rule.doc,
  };
}

// Severity overrides then acceptances, in that order, so an acceptance is judged
// against the rule the project actually runs. A reasonless acceptance is itself
// a blocking finding: the reason string is what makes the decision reviewable.
export function applyConfig(findings, config) {
  const out = [];
  for (let f of findings) {
    const override = config.rules[f.rule];
    if (override === 'advisory' || override === 'blocking') f = { ...f, severity: override };
    // A path ending in "/" accepts a whole subtree; otherwise the match is exact.
    const acceptance = config.accept.find(
      (a) => a.rule === f.rule &&
        (!a.path || a.path === f.file || (a.path.endsWith('/') && f.file.startsWith(a.path)))
    );
    if (acceptance) {
      if (typeof acceptance.reason === 'string' && acceptance.reason.trim()) continue;
      out.push({
        rule: 'config',
        severity: 'blocking',
        file: '.claudinite-checks.json',
        line: null,
        what: `acceptance for ${f.rule}${acceptance.path ? ` on ${acceptance.path}` : ''}${acceptance.pack ? ` (on the "${acceptance.pack}" pack entry)` : ''} has no reason`,
        why: 'the reason string is what makes an accepted violation reviewable',
        fix: 'add a non-empty "reason" to the acceptance entry',
        doc: 'engine/checks/README.md',
      });
    }
    out.push(f);
  }
  return out;
}

export function render(f) {
  const loc = f.line ? `${f.file}:${f.line}` : f.file;
  return [
    `[${f.severity.toUpperCase()}] ${f.rule}  ${loc}`,
    `  ${f.what}`,
    ...(f.why ? [`  Why: ${f.why}`] : []),
    `  Fix: ${f.fix}`,
    ...(f.doc ? [`  More: ${f.doc}`] : []),
  ].join('\n');
}

#!/usr/bin/env node
// World-scope conformance runner (see DESIGN.md): the rules that audit repo
// state as it exists now, plus the pack-agnostic settings/load integrity
// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
// this file shares no code with — only the scope-blind mechanism helpers
// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
// interview hygiene is a skill-owned check that rides its own pack's activation,
// and a malformed `questions` field is a load fault the pack registry reports.
// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
//   --changed   transitional: scope to files changed vs the merge-base with main
//               (adopting a repo with a backlog only — not the enforcement default)
//   --base REF  override the base ref
//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
import { writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { buildContext } from './helpers/repo-context.mjs';
import { discoverPacks, resolveDeclaredPacks } from '../pack_loader/pack-registry.mjs';
import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
import { reportFindings } from './report-findings.mjs';

const configError = (what, fix) => ({
  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
});

const args = process.argv.slice(2);
const has = (flag) => args.includes(flag);
const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
const root = value('--root') || process.cwd();

if (has('--list')) {
  const { packs } = await discoverPacks({ localRoot: root });
  for (const r of packRules(packs)) {
    console.log(`${r.id}\t${r.severity}\t${r.description}\t${r.doc}`);
  }
  process.exit(0);
}

if (has('--init')) {
  const path = join(root, '.claudinite-checks.json');
  if (existsSync(path)) {
    console.log(`${path} already exists — leaving it as-is.`);
    process.exit(0);
  }
  const { packs } = await discoverPacks({ localRoot: root });
  const ctx = buildContext({ root, mode: 'all' });
  // No pack is active by default, so the baseline is seeded as an explicit
  // declaration alongside the fingerprinted packs: every pack that flags
  // `seededByDefault` is written in (discovered structurally — the engine names
  // no pack), plus the ones a fingerprint detects. A seeded pack is still
  // opt-out-able where its own policy allows (baselining re-adds only the packs
  // whose absence it treats as drift), so removing a seeded declaration can
  // stick; each seeded pack ships its own one-time seed migration for the fleet.
  // Local packs are declared by hand, never fingerprinted or seeded — exclude
  // them from --init's seeding so a repo that already carries local packs (but
  // no config yet) doesn't auto-declare them.
  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
  // A pack can't be imported without its dependencies — pull each declared pack's
  // `requires` closure into the declaration so it's complete and visible.
  const declared = resolveDeclaredPacks(detected, packs);
  // maintenance.delivery is deliberately materialized, not defaulted — the selection
  // must be visible in the file where a project would change it (see engine/checks/README.md).
  // Only what carries a decision: the declaration and the always-explicit
  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
  // loadConfig defaults absent keys.
  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
  // The adoption interview (surfacing each declared pack's pending questions) is
  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
  // by the SessionStart interview-check step — not printed here, so this runner
  // imports no pack.
  process.exit(0);
}

const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });

// Settings/load integrity — pack-agnostic, so the world runner owns them.
// Settings validity is checked at load: malformed JSON, an unknown
// property, and a wrong pack name are all equally settings errors. loadConfig
// reports the first two; the runner adds unknown pack names (only it holds the
// registry) and broken/duplicate local pack.mjs faults.
const findings = [];
for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
for (const e of packErrors) findings.push(configError(e.what, e.fix));
// knownIds spans canon AND local packs, so a declared local pack id is valid and
// the unknown-pack message lists it among the declarable packs. ctx.config.packs
// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
// declaration already resolved through packEntryId.
const knownIds = new Set(packs.map((p) => p.id));
for (const name of ctx.config.packs) {
  if (typeof name === 'string' && !knownIds.has(name)) {
    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
  }
}
// (Adoption-interview hygiene is a skill-owned check that runs below with the
// other active-pack rules; a malformed `questions` field arrives as a load fault
// in packErrors above. Neither names a pack here.)

// The world rules: everything not scoped to the work. A broken contributedRules
// seam is a config-level fault surfaced here (the world runner owns diagnostics).
findings.push(...runActivePackRules(ctx, packs, {
  includeRule: (rule) => rule.scope !== 'work',
  onContributeError: (pack, e) => findings.push(configError(
    `the "${pack.id}" pack's contributedRules failed: ${e.message}`, 'fix the pack manifest, or the contribution it interprets')),
}));

const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'world', mode: ctx.mode, baseRef: ctx.baseRef });
process.exit(blocking ? 1 : 0);
=== run-active-pack-rules
// Scope-blind mechanism (no policy, no scope knowledge): given a built context
// and the discovered packs, run the ACTIVE packs' rules that a caller-supplied
// predicate admits, and return their findings. The world and work runners each
// call this with their own `includeRule` — this file never names a scope, so
// the two runners stay independent of each other while sharing the walk.
import { runRule } from './helpers/work.mjs';
import { isActive } from '../pack_loader/pack-registry.mjs';

// A pack's contributedRules seam: the pack interprets the contributions other
// packs address to it on their manifests (`contributes`), returning first-class
// rules — how packs compose through declaration + configuration instead of
// importing each other's code. Isolated per pack, like manifest loading: one
// broken seam (a consumer-authored local pack's, say) must not sink the run.
// `onError` lets a caller turn a broken seam into a finding; passing none
// swallows it (a runner that doesn't own config diagnostics stays quiet).
export function contributedRules(pack, fromPacks, onError = null) {
  try { return pack.contributedRules?.(fromPacks) ?? []; }
  catch (e) { onError?.(e); return []; }
}

// The full rule catalog the given packs carry, id-sorted: a pack's own rules,
// the checks its bundled skills own, and the rules built from contributions
// addressed to it. The ONE place the three sources are summed — `--list`
// prints it and the catalog's own tally guard counts it, so neither can
// disagree with the runner about what rules exist, and a fourth source added
// later lands in both for free.
export function packRules(packs) {
  return [
    ...packs.flatMap((p) => p.rules ?? []),
    ...packs.flatMap((p) => p.skillChecks ?? []),
    ...packs.flatMap((p) => contributedRules(p, packs)),
  ].sort((a, b) => a.id.localeCompare(b.id));
}

// Every finding from the active packs' rules that `includeRule` admits. A rule
// turned `off` in settings is skipped. `onContributeError(pack, err)` is invoked
// when a pack's contributedRules seam throws (the caller decides whether that
// becomes a finding).
export function runActivePackRules(ctx, packs, { includeRule, onContributeError = null }) {
  const findings = [];
  // Expose the discovered packs to any rule that reasons about pack metadata
  // (e.g. the adoption-interview hygiene check reads each active pack's declared
  // questions) — checks run synchronously and can't re-discover packs themselves.
  ctx.packs = packs;
  const activePacks = packs.filter((p) => isActive(p, ctx.config));
  for (const pack of activePacks) {
    const contributed = contributedRules(pack, activePacks,
      onContributeError ? (e) => onContributeError(pack, e) : null);
    for (const rule of [...(pack.rules ?? []), ...(pack.skillChecks ?? []), ...contributed]) {
      if (!includeRule(rule)) continue;
      if (ctx.config.rules[rule.id] === 'off') continue;
      findings.push(...runRule(rule, ctx));
    }
  }
  return findings;
}

// THE PACK MANIFEST SPEC — the single declarative statement of what a
// `pack.mjs` may and must carry. Everything a pack declares about itself is
// described here once, and `validateManifest` is the only thing that judges a
// manifest against it. The loader calls it on every pack it imports (canon and a
// consumer's own `local_packs/` alike), so a malformed or incomplete manifest
// surfaces as a blocking `config` error at load — the same class as invalid JSON
// in `.claudinite-checks.json`.
//
// WHY A SPEC AND NOT A CHECK. A required manifest field is part of the pack
// contract, not a conformance opinion about a repo's content: a conformance rule
// would have to be declared BY a pack, run only when that pack is active, and
// re-derive the manifest by reading its source text — enforcing the shape of the
// system from inside one of its members. The spec is upstream of every pack, so
// there is nothing to declare and nothing to parse.
//
// Dependency-free by the engine's module rule: no imports, no filesystem. The
